/* Segmented allocator for retail CD bodies made unreachable by the compact
 * resident core. The table is generated by build_cd_objects.py from the
 * redirect-aware carve list; callback/status ABI words and entry veneers are
 * never included. */
typedef unsigned int u32;
extern int nfs4_GteEnterRace(void);
#include "cd_arena_table.inc"

static volatile u32 nfs4_cd_arena_index;
static volatile u32 nfs4_cd_arena_used;

void nfs4_CdArenaReset(void)
{
    nfs4_cd_arena_index=0;
    nfs4_cd_arena_used=0;
}

u32 nfs4_CdArenaCapacity(void)
{
    u32 i,total=0;
    for(i=0;i<NFS4_CD_ARENA_COUNT;i++)total+=nfs4_cd_arena_size[i];
    return total;
}

void *nfs4_CdArenaAlloc(u32 size,u32 align)
{
    u32 i=nfs4_cd_arena_index,used=nfs4_cd_arena_used,start,p;
    if(align==0)align=1;
    while(i<NFS4_CD_ARENA_COUNT){
        start=nfs4_cd_arena_start[i];
        p=(start+used+align-1)&~(align-1);
        if(p+size<=start+nfs4_cd_arena_size[i]){
            nfs4_cd_arena_index=i;
            nfs4_cd_arena_used=p+size-start;
            return(void *)p;
        }
        i++;
        used=0;
    }
    return 0;
}

int nfs4_CdEnterRace(void)
{
    int result=nfs4_GteEnterRace();
    nfs4_CdArenaReset();
    return result;
}
